end

function LevelGuideMainEntrance:Awake()
    UIEventProxy.Create(self.BtnLevelGuideEntrance.gameObject).onPointerClick = Bind(self, self.OnClickEntranceAction)
end

function LevelGuideMainEntrance:OnDestroy()

    self.controller = nil--luabehaviour 中CSharp对象 self:Delete()
    self:Delete()
    self = nil
end

function LevelGuideMainEntrance:InitData()
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    ---@type PlayerDojo
    local playerDojo = playerComponent.playerDojo
    return {newbieGuideTaskReceived = playerDojo.newbieGuideTaskReceived, newbieGuideTaskCurrentId = playerDojo.newbieGuideTaskCurrentId}
end

