function LevelGuideMainEntrance:RefreshUI()

    local data = self:InitData()
    self.data = data

    local currentId = data.newbieGuideTaskCurrentId

    ---@type LevelGuideVo
    local levelGuideVo = CfUtils.GetCfVo(AutoIds.IdSetting122, "LevelGuideVo", currentId)
    self.Text.text = levelGuideVo.title

    local isShowEffect = self:CheckIsCompleteProgress(levelGuideVo.taskContentType, levelGuideVo.taskContentId, levelGuideVo.taskContentNum)
    KTool.SetActive(self.DefaultNode.gameObject, not isShowEffect)
    KTool.SetActive(self.ActiveNode.gameObject, isShowEffect)
    
    local go = GameUtils.GetRedPointGo(self.ActiveNode)
    if go then
        KTool.SetActive(go, isShowEffect)
    end
end

function LevelGuideMainEntrance:CheckIsCompleteProgress(type, taskContentId, taskContentNum)
    local config = {
        [TaskType.QuestType] = Constants.CommonUnlockType.PassQuest,
        [TaskType.LevelLimit] = Constants.CommonUnlockType.PlayerLevel,
    }
    local targetNumConfig = {
        [TaskType.QuestType] = taskContentId,
        [TaskType.LevelLimit] = taskContentNum,
    }
    local unlockType = config[type]
    if unlockType == nil then
        return false
    end
    return GameUtils.IsUnlockedSingle(unlockType, targetNumConfig[type])
end

